import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"IIFL (XTS)","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/iifl-xts.md","filePath":"connect-brokers/brokers/iifl-xts.md"}'),s={name:"connect-brokers/brokers/iifl-xts.md"};function n(i,e,p,l,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="iifl-xts" tabindex="-1">IIFL (XTS) <a class="header-anchor" href="#iifl-xts" aria-label="Permalink to &quot;IIFL (XTS)&quot;">​</a></h1><p>IIFL Securities provides API access through the XTS (Symphony Fintech) platform, served from <code>https://ttblaze.iifl.com</code>. Tradeboard&#39;s <code>iifl</code> plugin talks to two XTS endpoints: the Interactive API for orders, positions and holdings, and the Market Data API for quotes, depth and historical candles.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This page covers the <strong>XTS</strong> integration, which Tradeboard registers as the broker <code>iifl</code>. IIFL also runs a separate Markets&#39; APIs developer portal used by the <a href="./iifl-capital.html">IIFL Capital</a> plugin (broker <code>iiflcapital</code>). The two are different products with different credentials. Pick the one your account is enabled for.</p></div><hr><h3 id="step-1-create-api-applications" tabindex="-1">Step 1: Create API Applications <a class="header-anchor" href="#step-1-create-api-applications" aria-label="Permalink to &quot;Step 1: Create API Applications&quot;">​</a></h3><p>Log in to the IIFL XTS developer dashboard with your IIFL credentials.</p><p>Once logged in:</p><ol><li>Go to <code>My App</code> &gt; <code>Create New Application</code></li><li>Create two separate apps:</li></ol><ul><li><strong>Interactive Order API</strong></li><li><strong>Market Data API</strong></li></ul><p><strong>Details to Fill:</strong></p><ul><li><strong>App Name</strong>: Tradeboard</li><li><strong>App Description</strong>: Tradeboard</li><li><strong>Redirect URL: (leave it empty)</strong></li><li><strong>Company Name</strong>: Tradeboard (or your own)</li><li>Choose the correct <strong>API Package</strong> depending on the app (Order or Market Data).</li></ul><p>Once submitted, wait for approval from the broker. After approval, the status will turn <strong>Active</strong>.</p><hr><h3 id="step-2-setup-environment-variables" tabindex="-1">Step 2: Setup Environment Variables <a class="header-anchor" href="#step-2-setup-environment-variables" aria-label="Permalink to &quot;Step 2: Setup Environment Variables&quot;">​</a></h3><p>Each app issues its own App Key and Secret Key. The Interactive app&#39;s pair goes into the plain variables, the Market Data app&#39;s pair into the <code>_MARKET</code> variables. Refer to the <code>.sample.env</code> file in your Tradeboard folder and prepare your <code>.env</code> as follows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;YOUR_BROKER_ORDER_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;YOUR_ORDER_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BROKER_API_KEY_MARKET = &#39;YOUR_BROKER_MARKET_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET_MARKET = &#39;YOUR_BROKER_MARKET_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/iifl/callback&#39;</span></span></code></pre></div><p>Replace the values with actual credentials shown on your developer dashboard once approved.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Swapping the Interactive and Market Data pairs is the most common setup mistake. The login then succeeds but quotes stay empty, because the market data session was never established.</p></div><hr><h3 id="step-3-start-tradeboard" tabindex="-1">Step 3: Start Tradeboard <a class="header-anchor" href="#step-3-start-tradeboard" aria-label="Permalink to &quot;Step 3: Start Tradeboard&quot;">​</a></h3><p>Once all environment variables are set and both apps are <strong>Active</strong>, start Tradeboard and click <strong>Connect</strong> on the IIFL (XTS) broker page. There is no broker login screen to complete: Tradeboard posts your App Key and Secret Key straight to the XTS session endpoint and receives the interactive token, the market data feed token and your user id in one step.</p><p>This completes the integration process for IIFL (XTS) with Tradeboard.</p><p>Integrating Tradeboard with IIFL&#39;s XTS API empowers traders and developers to automate and streamline their trading workflows with precision and speed. By using both the order execution and market data APIs, you can build robust trading systems capable of reacting to market conditions in real time. Always ensure secure handling of API credentials, implement proper error handling, and monitor your integration to maintain reliability and compliance.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/iifl/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,26)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
